package sites

import (
	"errors"
	"net/http"

	"github.com/0xJacky/Nginx-UI/internal/site"
	"github.com/gin-gonic/gin"
	"github.com/spf13/cast"
	"github.com/uozi-tech/cosy"
)

// forceOption reads ?force=1, which lets a request change a site generated by
// an ingress.
func forceOption(c *gin.Context) site.MutateOption {
	return site.Force(isForced(c))
}

func isForced(c *gin.Context) bool {
	return cast.ToBool(c.Query("force"))
}

// respondSiteError answers ErrSiteManagedByIngress with 409 Conflict so callers
// can tell a refused change from a failure; other errors go through cosy.
func respondSiteError(c *gin.Context, err error) {
	if site.IsManagedByIngress(err) {
		var cErr *cosy.Error
		errors.As(err, &cErr)
		c.JSON(http.StatusConflict, cErr)
		return
	}
	cosy.ErrHandler(c, err)
}

// rejectManagedSites checks every name before a batch starts, so a batch that
// includes a site generated by an ingress changes nothing instead of stopping
// halfway. It responds and reports true when the batch must stop.
func rejectManagedSites(c *gin.Context, names []string, opt site.MutateOption) bool {
	for _, name := range names {
		if rejectInvalidSiteName(c, name) {
			return true
		}
		if err := site.CheckManaged(name, opt); err != nil {
			respondSiteError(c, err)
			return true
		}
	}
	return false
}
